import{_ as o,o as t,c as a,a4 as l}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"moonlight-host 开发结论","description":"","frontmatter":{"title":"moonlight-host 开发结论","date":"2026-06-28T00:00:00.000Z"},"headers":[],"relativePath":"posts/moonlight-host-结论.md","filePath":"posts/moonlight-host-结论.md"}'),r={name:"posts/moonlight-host-结论.md"};function s(i,e,d,n,c,h){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="moonlight-host-开发结论" tabindex="-1">moonlight-host 开发结论 <a class="header-anchor" href="#moonlight-host-开发结论" aria-label="Permalink to &quot;moonlight-host 开发结论&quot;">​</a></h1><h2 id="最终产出的二进制-minimal-standalone" tabindex="-1">最终产出的二进制（minimal standalone） <a class="header-anchor" href="#最终产出的二进制-minimal-standalone" aria-label="Permalink to &quot;最终产出的二进制（minimal standalone）&quot;">​</a></h2><p><strong><code>moonlight-host.exe</code></strong> — 10.5 MB，单文件，无外部 DLL 依赖</p><ul><li>工具链：Rust nightly + MinGW-w64 GCC 16.1.0 + LLVM 19.1.7</li><li>目标：<code>x86_64-pc-windows-gnu</code></li><li>构建命令：<code>cargo build -p moonlight-host --target x86_64-pc-windows-gnu --release</code></li><li>strip 后大小：10.5 MB（<code>llvm-strip --strip-all</code>）</li><li>功能：<code>health/pair/apps/cancel/serve</code> 五个子命令</li></ul><h2 id="关键问题-解决" tabindex="-1">关键问题 &amp; 解决 <a class="header-anchor" href="#关键问题-解决" aria-label="Permalink to &quot;关键问题 &amp; 解决&quot;">​</a></h2><h3 id="_1-openssl-sys-编译失败-gnu-target" tabindex="-1">1. openssl-sys 编译失败（GNU target） <a class="header-anchor" href="#_1-openssl-sys-编译失败-gnu-target" aria-label="Permalink to &quot;1. openssl-sys 编译失败（GNU target）&quot;">​</a></h3><ul><li><strong>问题</strong>：openssl-sys 默认尝试 vendored 编译，耗时 &gt;10 分钟且容易失败</li><li><strong>解决</strong>： <ul><li><code>OPENSSL_NO_VENDOR=1</code> — 强制使用系统 OpenSSL</li><li><code>OPENSSL_ROOT_DIR</code> + <code>OPENSSL_LIB_DIR</code> + <code>OPENSSL_INCLUDE_DIR</code> — 指定 MSYS2 UCRT64 路径</li><li><code>BINDGEN_EXTRA_CLANG_ARGS_x86_64_pc_windows_gnu</code> — 指定 bindgen target</li></ul></li></ul><h3 id="_2-rustls-运行时-panic" tabindex="-1">2. rustls 运行时 panic <a class="header-anchor" href="#_2-rustls-运行时-panic" aria-label="Permalink to &quot;2. rustls 运行时 panic&quot;">​</a></h3><ul><li><strong>问题</strong>：<code>CryptoProvider</code> 未初始化（缺少 <code>ring</code> feature）</li><li><strong>解决</strong>：在 host 的 Cargo.toml 中加入 <code>rustls = { workspace = true }</code>，确保 feature 传递</li></ul><h3 id="_3-二进制体积优化" tabindex="-1">3. 二进制体积优化 <a class="header-anchor" href="#_3-二进制体积优化" aria-label="Permalink to &quot;3. 二进制体积优化&quot;">​</a></h3><ul><li>workspace <code>[profile.release]</code>：<code>strip = &quot;symbols&quot;</code>, <code>lto = &quot;fat&quot;</code>, <code>codegen-units = 1</code>, <code>panic = &quot;abort&quot;</code></li><li>moonlight-host 覆写：<code>opt-level = &quot;z&quot;</code></li><li>最终 <strong>10.5 MB</strong>（vs MSVC 4 MB + 8.7 MB DLL）</li></ul><h3 id="_4-msvc-方案尝试-放弃" tabindex="-1">4. MSVC 方案尝试（放弃） <a class="header-anchor" href="#_4-msvc-方案尝试-放弃" aria-label="Permalink to &quot;4. MSVC 方案尝试（放弃）&quot;">​</a></h3><ul><li>MSVC 目标 + clang-cl + lld-link → 4 MB 但需 <code>libcrypto-3-x64.dll</code> + <code>libssl-3-x64.dll</code></li><li>vendored OpenSSL 构建失败（缺 perl，超时）</li><li>结论：<strong>GNU 单文件方案更优</strong></li></ul><h3 id="_5-上游-web-server-配置问题" tabindex="-1">5. 上游 web-server 配置问题 <a class="header-anchor" href="#_5-上游-web-server-配置问题" aria-label="Permalink to &quot;5. 上游 web-server 配置问题&quot;">​</a></h3><ul><li><strong>streamer_path 指向错误路径</strong>：MSVC 默认路径 <code>target\\release\\streamer.exe</code> 不存在</li><li><strong>修复</strong>：改为 <code>target\\x86_64-pc-windows-gnu\\release\\streamer.exe</code></li><li><strong>data.json 用户 ID 不匹配</strong>：config 中 <code>default_user_id: 4160598498</code> 但 data.json 实际是 <code>4058998160</code></li><li><strong>前端 static 目录找不到</strong>：工作目录需指向 <code>package/</code>，而非 <code>server/</code></li></ul><h2 id="最终状态" tabindex="-1">最终状态 <a class="header-anchor" href="#最终状态" aria-label="Permalink to &quot;最终状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>状态</th></tr></thead><tbody><tr><td><code>moonlight-host</code> CLI（health/pair/apps/cancel）</td><td>✅ 全部通过</td></tr><tr><td><code>moonlight-host serve</code>（WS↔IPC bridge）</td><td>✅ Handshake + Init 通过</td></tr><tr><td><code>streamer.exe</code>（GNU 编译）</td><td>✅ 路径正确，上游 web-server 串流成功</td></tr><tr><td>上游 web-server ↔ Sunshine 串流</td><td>✅ 视频流输出正常</td></tr><tr><td>二进制部署大小</td><td>10.5 MB 单文件</td></tr></tbody></table><h2 id="后续方向" tabindex="-1">后续方向 <a class="header-anchor" href="#后续方向" aria-label="Permalink to &quot;后续方向&quot;">​</a></h2><ol><li>用 <code>moonlight-host serve</code> 替换上游 web-server，HomeSense 直接启动 moonlight-host 替代 web-server</li><li>修改 <code>streaming-gateway.service.ts</code>（spawn moonlight-host 替代 web-server）</li><li>简化 <code>moonlight-web-runtime.service.ts</code></li><li>对比 moonlight-host 与上游 web-server 的串流稳定性</li></ol>',19)])])}const m=o(r,[["render",s]]);export{u as __pageData,m as default};
